return {
    ["CodesUtil"] = {
        ["generateCode"] = function(p1) --[[ Line: 11 ]]
            local v2 = false
            local v3 = 0
            local v4 = ""
            while true do
                if v2 then
                    v3 = v3 + 1
                else
                    v2 = true
                end
                if v3 >= p1 then
                    return v4
                end
                local v5 = math.random() * 34
                local v6 = math.ceil(v5)
                v4 = v4 .. string.sub("ABCDEFGHIJKLMNPQRSTUVWXYZ123456789", v6, v6)
            end
        end,
        ["displayCode"] = function(p7, p8, p9) --[[ Line: 42 ]]
            local v10 = #p7 / p9
            local v11 = math.ceil(v10)
            local v12 = false
            local v13 = 1
            local v14 = {}
            while true do
                if v12 then
                    v13 = v13 + 1
                else
                    v12 = true
                end
                if v13 >= v11 + 1 then
                    local v15 = p8 == nil and ", " or p8
                    return table.concat(v14, v15)
                end
                local v16 = (v13 - 1) * p9 + 1
                local v17 = v13 * p9
                local v18 = string.sub(p7, v16, v17)
                table.insert(v14, v18)
            end
        end
    }
}